'use strict';
  const modalHeader = (eyebrow, title, detail) => `<div class="sticky top-0 z-10 flex items-start gap-4 border-b border-slate-200 bg-white/95 px-5 py-4 backdrop-blur-xl sm:px-6"><div class="min-w-0 flex-1"><p class="eyebrow">${e(eyebrow)}</p><h2 id="admin-modal-title" class="mt-1 font-display text-xl font-extrabold text-slate-950">${e(title)}</h2><p class="mt-1 text-xs leading-5 text-slate-500">${e(detail)}</p></div><button class="icon-btn" data-modal-close aria-label="Close dialog">${ICON.close}</button></div>`;

  function userModal() {
    const classes = Store.listClasses().filter((item) => item.status === 'active');
    const editing = Store.listUsers().find((item) => item.id === p().get('edit')) || null;
    openModal(`${modalHeader('User management', editing ? 'Edit user' : 'Add a user', 'Choose roles and classes first; type only the identity details that cannot be inferred.')}<form id="user-create-form" class="p-5 sm:p-6"><div class="grid gap-5"><div><span class="field-label">Role</span><div class="mt-2 flex flex-wrap gap-2" role="group" aria-label="User role">${['student', 'teacher', 'administrator'].map((role) => `<button type="button" class="choice-chip" data-role-choice="${role}" aria-pressed="${editing ? editing.role === role : role === 'student'}">${role}</button>`).join('')}</div></div><label><span class="field-label">Full name</span><input id="new-user-name" class="field mt-2" autocomplete="name" placeholder="Amina Yusuf Bello" value="${e(editing?.fullName || '')}" required></label><div id="user-class-field"><span class="field-label">Class</span><div class="mt-2 flex flex-wrap gap-2">${classes.map((cls) => `<button type="button" class="choice-chip" data-class-choice="${e(cls.id)}" aria-pressed="${editing?.classId === cls.id}">${e(cls.name)}</button>`).join('')}</div></div><label><span class="field-label">Guardian name <span class="font-medium text-slate-400">optional</span></span><input id="new-user-guardian" class="field mt-2" placeholder="Guardian or parent" value="${e(editing?.guardian || '')}"></label><div id="user-create-error" class="hidden alert alert-danger" role="alert"></div></div><div class="mt-6 flex justify-end gap-2"><button type="button" class="btn btn-secondary" data-modal-close>Cancel</button><button class="btn btn-primary" type="submit">${editing ? 'Save changes' : 'Add user'}</button></div></form>`);
    let role = editing?.role || 'student', classId = editing?.classId || '';
    document.getElementById('user-class-field').classList.toggle('hidden', role !== 'student');
    modal.querySelectorAll('[data-role-choice]').forEach((button) => button.addEventListener('click', () => { role = button.dataset.roleChoice; modal.querySelectorAll('[data-role-choice]').forEach((item) => item.setAttribute('aria-pressed', String(item === button))); document.getElementById('user-class-field').classList.toggle('hidden', role !== 'student'); }));
    modal.querySelectorAll('[data-class-choice]').forEach((button) => button.addEventListener('click', () => { classId = button.dataset.classChoice; modal.querySelectorAll('[data-class-choice]').forEach((item) => item.setAttribute('aria-pressed', String(item === button))); }));
    document.getElementById('user-create-form').addEventListener('submit', (event) => { event.preventDefault(); const error = document.getElementById('user-create-error'); try { if (role === 'student' && !classId) throw new Error('Choose a class for the student.'); Store.saveUser({ id: editing?.id, fullName: document.getElementById('new-user-name').value, guardian: document.getElementById('new-user-guardian').value, role, classId, status: editing?.status || 'active', joinedAt: editing?.joinedAt }); closeModal(); toast(editing ? 'User updated.' : 'User added to the local administration directory.', 'success'); render(); } catch (failure) { error.textContent = failure.message; error.classList.remove('hidden'); } });
  }

  function classModal() {
    const editing = Store.listClasses().find((item) => item.id === p().get('edit')) || null;
    openModal(`${modalHeader('Class management', editing ? 'Edit class' : 'Create a class', 'Use level, stream and capacity presets; a class name is generated automatically.')}<form id="class-create-form" class="p-5 sm:p-6"><div class="grid gap-5"><div><span class="field-label">Level</span><div class="mt-2 flex gap-2">${['SS1', 'SS2', 'SS3'].map((level) => `<button type="button" class="choice-chip" data-level-choice="${level}" aria-pressed="${editing ? editing.classLevel === level : level === 'SS1'}">${level}</button>`).join('')}</div></div><div><span class="field-label">Stream</span><div class="mt-2 flex flex-wrap gap-2">${['General', 'Science', 'Arts', 'Social Science'].map((stream) => `<button type="button" class="choice-chip" data-stream-choice="${stream}" aria-pressed="${editing ? editing.stream === stream : stream === 'General'}">${stream}</button>`).join('')}</div></div><div><span class="field-label">Capacity</span><div class="mt-2 flex flex-wrap gap-2">${[30, 40, 50, 60, 80].map((cap) => `<button type="button" class="choice-chip" data-capacity-choice="${cap}" aria-pressed="${editing ? Number(editing.capacity) === cap : cap === 40}">${cap} seats</button>`).join('')}</div></div><label><span class="field-label">Room <span class="font-medium text-slate-400">optional</span></span><select id="new-class-room" class="field mt-2"><option value="">No room yet</option>${['Senior Block A','Science Wing','Humanities Wing','Commerce Wing','ICT Lab'].map((room)=>`<option ${editing?.room===room?'selected':''}>${room}</option>`).join('')}</select></label><div id="class-create-preview" class="surface-soft p-4 text-sm"></div><div id="class-create-error" class="hidden alert alert-danger" role="alert"></div></div><div class="mt-6 flex justify-end gap-2"><button type="button" class="btn btn-secondary" data-modal-close>Cancel</button><button class="btn btn-primary" type="submit">${editing ? 'Save changes' : 'Create class'}</button></div></form>`);
    let level = editing?.classLevel || 'SS1', stream = editing?.stream || 'General', capacity = Number(editing?.capacity) || 40;
    const update = () => { document.getElementById('class-create-preview').innerHTML = `<span class="eyebrow">Preview</span><strong class="mt-2 block font-display text-lg text-slate-950">${e(level)} ${e(stream)}</strong><span class="mt-1 block text-xs text-slate-500">${capacity} student capacity</span>`; };
    const choice = (selector, valueKey, setter) => modal.querySelectorAll(selector).forEach((button) => button.addEventListener('click', () => { setter(button.dataset[valueKey]); modal.querySelectorAll(selector).forEach((item) => item.setAttribute('aria-pressed', String(item === button))); update(); }));
    choice('[data-level-choice]', 'levelChoice', (v) => { level = v; }); choice('[data-stream-choice]', 'streamChoice', (v) => { stream = v; }); choice('[data-capacity-choice]', 'capacityChoice', (v) => { capacity = Number(v); }); update();
    document.getElementById('class-create-form').addEventListener('submit', (event) => { event.preventDefault(); const error = document.getElementById('class-create-error'); try { const name = `${level} ${stream}`; Store.saveClass({ id: editing?.id, name, classLevel: level, stream, capacity, room: document.getElementById('new-class-room').value, status: editing?.status || 'active' }); closeModal(); toast(editing ? `${name} updated.` : `${name} created.`, 'success'); render(); } catch (failure) { error.textContent = failure.message; error.classList.remove('hidden'); } });
  }

  const availableQuestionCount = (draft) => {
    try {
      const probe = Store.normalizeSession({ ...draft, questionCount: 100, title: draft.title || 'Question availability probe' });
      return Data.questionsForSession(data, probe).length;
    } catch { return 0; }
  };

  const WIZARD_KEY = 'festacol.admin.exam-draft.v1';
  const wizardDraft = () => { try { return JSON.parse(sessionStorage.getItem(WIZARD_KEY)) || {}; } catch { return {}; } };
  const saveWizard = (value) => sessionStorage.setItem(WIZARD_KEY, JSON.stringify(value));
  const clearWizard = () => sessionStorage.removeItem(WIZARD_KEY);
